const runtimeSha256=await codeHashes(),startTick=s.worldTick,started=performance.now();
const trace=[],checkpoints=[],paths=[],facts=[],seenFacts=new Set(Object.keys(s.factsById)),sourcePeople=Object.keys(s.personsById);
let status=dryRun?'planned':'failed',failure=null,advances=0,checkpointRoundtrip=null;
