  const blocker=s.personsById[s.master.scenic.waitingForPersonId];assert(blocked.phase==='moving'&&blocked.progressTicks===0&&blocker?.mind?.scenic?.waitingForPersonId===MASTER,'harvest has no physical progress; stop before spending further world time');assert(attempts++<1,'one public retreat was insufficient; preserve the blocked harvest');
  const retreat=harvestRetreat(blocker),resource=blocked.resource,harvestTarget=copy(blocked.target),before=metrics(),origin=copy(blocker.mind.scenic),patchBefore=s.srEconomy.patches[resource].remaining,carriedBefore=copy(stocks()[CARRIED]?.resources||{});
