function leaveFacility(){let a=s.activitiesById[s.master.activityId];if(a?.kind==='sr-transport'){settleTransport(a.workOrderId);a=s.activitiesById[s.master.activityId];}if(a?.kind==='facility'){if(a.phase!=='executing')return;const b=s.buildingsById[a.targetId];assert(b,'saved facility exists');const p=buildingAccess(s,b);walkHome(p.x,p.y,'leave the retained facility through its actual entrance');}assert(!s.master.activityId,'finish the current body order first');}
function rest(target=90){if(s.master.energy>=target&&s.master.wound===0)return;assert(home(),'rest and treatment require returning home in this continuation');leaveFacility();command('masterAction',s.master.wound>0?'heal':'rest');advanceUntil(()=>s.master.energy>=target&&s.master.wound===0,'recover through real bed rest/treatment');leaveFacility();}
