function ensureHerbs(target){assert(home());leaveFacility();unload();while(amount(HOME,'herb')+1e-8<target){budget();ensureFood();if(!harvestAvailable(s,'herb',HARVEST_BATCH.herb))replenish('herb');harvest('herb');transport(CARRIED,HOME,{herb:amount(CARRIED,'herb')});}}
