function fund(target){assert(home(),'funding starts at home');leaveFacility();unload();while(amount(HOME,'jade')+1e-8<target){budget();rest(55);ensureFood();if(amount(HOME,'wood')<20){const sourceStock=Object.values(stocks()).filter(st=>st.ownerId===MASTER&&st.access==='public'&&st.id!==HOME&&(st.resources.wood||0)>=10).sort((a,b)=>b.resources.wood-a.resources.wood)[0];if(sourceStock)transport(sourceStock.id,HOME,{wood:Math.min(40,sourceStock.resources.wood)});else{if(!harvestAvailable(s,'wood',HARVEST_BATCH.wood))replenish('wood');harvest('wood');transport(CARRIED,HOME,{wood:amount(CARRIED,'wood')});}}
 approachHomeMerchant();const batches=Math.min(8,Math.floor(amount(HOME,'wood')/10),Math.ceil((target-amount(HOME,'jade'))/7));assert(batches>0,'wood sale has a real quantity');const beforeJade=amount(HOME,'jade'),beforeWood=amount(HOME,'wood');command('marketTrade','wood','sell',batches);assert.equal(beforeWood-amount(HOME,'wood'),batches*10);assert.equal(amount(HOME,'jade')-beforeJade,batches*7);}}
