 const candidates=s.disciples.map(p=>({p,opportunity:SIM.workOpportunity(s,p,library),contributed:order?.phase!=='completed'?(order?.contributions[p.personId]||0):0,yield:SIM.buildingYield(s,library,p).insight||0})).filter(c=>c.opportunity.available&&c.p.energy>=35).sort((a,b)=>b.contributed-a.contributed||b.yield-a.yield||b.p.energy-a.p.energy);
